import{_ as a,o,c as t,a2 as r}from"./chunks/framework.DTdEDYjJ.js";const h=JSON.parse('{"title":"Game SVG artwork sources","description":"","frontmatter":{},"headers":[],"relativePath":"public/experience/renderer/assets/game/LICENSES.md","filePath":"public/experience/renderer/assets/game/LICENSES.md"}'),i={name:"public/experience/renderer/assets/game/LICENSES.md"};function n(s,e,c,d,l,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="game-svg-artwork-sources" tabindex="-1">Game SVG artwork sources <a class="header-anchor" href="#game-svg-artwork-sources" aria-label="Permalink to &quot;Game SVG artwork sources&quot;">​</a></h1><p>Mahjong: FluffyStuff, riichi-mahjong-tiles, commit 26e127ba2117f45cdce5ea0225748cc0cfad3169. <a href="https://github.com/FluffyStuff/riichi-mahjong-tiles" target="_blank" rel="noreferrer">https://github.com/FluffyStuff/riichi-mahjong-tiles</a> Upstream LICENSE.md dedicates all artwork to the public domain under CC0 1.0. 34 face motifs. Editor-specific metadata/elements are removed without rasterization. The original plain red back is replaced by an original OpenBot green back.</p><p>Mahjong bodies and back: Copyright (c) 2026 OpenBot contributors, MIT License. Templates: scripts/game-art-templates/mahjong-face-surface.svg and mahjong-back.svg. Each of the 34 motifs is composed over the complete ivory/green vector body; Back.svg is the complete original green/porcelain vector back. All 35 stand alone.</p><p>Poker: Adrian Kennard (RevK), <a href="https://www.me.uk/cards/" target="_blank" rel="noreferrer">https://www.me.uk/cards/</a> . Artwork generated by the author&#39;s public SVG deck generator, standard poker/normal pips/Goodall-style courts/Diamond back. The author explicitly dedicates these designs to CC0 1.0. Generator software is separate; no GPL generator code is shipped. 54 files: 52 standard faces and monochrome/colorful Jokers. No Alteran artwork is included. The original fine Diamond back is replaced by an original OpenBot green/ivory vector back that remains recognizable at native table size. Template scripts/game-art-templates/poker-back.svg, Copyright (c) 2026 OpenBot contributors, MIT License. The complete deck contains 55 files.</p><p>Rails (铁道计划): the train cards, destination ticket, train piece and game icon are original OpenBot MIT vector artwork composed from primitive shapes. See rails/README.md for the method and manifest.json for per-file digests.</p><p>Tycoon (大富翁): icons/tycoon.svg is original OpenBot MIT vector artwork. Board tiles, dice and player tokens are DOM-rendered from theme variables and ship no separate assets.</p><p>Caravan Routes: the tea, silk, porcelain, jade and camel goods cards, card back and game icon are original OpenBot MIT flat-vector artwork. Per-file digests are recorded in manifest.json under <code>caravan</code> and <code>icons</code>.</p><p>Lantern Watch: the four lighthouse towers, lamp, storm and game icon are original OpenBot MIT vector artwork. Per-file digests are recorded in manifest.json under <code>files</code> and <code>icons</code>.</p><p>Two additional standalone game icons in icons/ are original OpenBot MIT artwork.</p><p>Sealed-Bid Auction (暗标拍卖会): the seven files under lots/ and the third icon in icons/sealed-bid.svg are original OpenBot artwork, hand-authored flat vector. One motif per collecting family (tea, silk, porcelain, jade, ink, lacquer) plus the auction icon. Copyright (c) 2026 OpenBot contributors, MIT License. They are drawn from scratch as paths: no raster source, no font conversion, no tracing of a third-party design, and no protected game characters or art. Their digests and byte sizes are recorded in manifest.json under <code>lots</code> and <code>files</code>.</p><p>CC0 1.0: <a href="https://creativecommons.org/publicdomain/zero/1.0/" target="_blank" rel="noreferrer">https://creativecommons.org/publicdomain/zero/1.0/</a> . Adaptations: local filenames unchanged, editor metadata and editor-specific attributes removed, static vector-only validation. No raster images, webfonts, scripts, external links or network resources are embedded. Full source and imported file digests and deck options are in manifest.json.</p><h2 id="mit-license-for-original-openbot-tile-bodies-and-back" tabindex="-1">MIT License for original OpenBot tile bodies and back <a class="header-anchor" href="#mit-license-for-original-openbot-tile-bodies-and-back" aria-label="Permalink to &quot;MIT License for original OpenBot tile bodies and back&quot;">​</a></h2><p>MIT License</p><p>Copyright (c) 2026 OpenBot contributors</p><p>Permission is hereby granted, free of charge, to any person obtaining a copy of this software and associated documentation files (the &quot;Software&quot;), to deal in the Software without restriction, including without limitation the rights to use, copy, modify, merge, publish, distribute, sublicense, and/or sell copies of the Software, and to permit persons to whom the Software is furnished to do so, subject to the following conditions:</p><p>The above copyright notice and this permission notice shall be included in all copies or substantial portions of the Software.</p><p>THE SOFTWARE IS PROVIDED &quot;AS IS&quot;, WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.</p>',17)])])}const f=a(i,[["render",n]]);export{h as __pageData,f as default};
